// Verifying an OIDC ID token (Node.js with jose library)
import { createRemoteJWKSet, jwtVerify } from 'jose';

const JWKS = createRemoteJWKSet(
  new URL('https://accounts.google.com/.well-known/openid-configuration')
);

async function verifyIdToken(idToken) {
  const { payload } = await jwtVerify(idToken, JWKS, {
    issuer: 'https://accounts.google.com',
    audience: process.env.GOOGLE_CLIENT_ID,
  });
  // payload.sub is the stable unique user identifier
  return payload;
}

// WebAuthn passkey authentication (browser side)
async function loginWithPasskey() {
  // Fetch challenge from server
  const opts = await fetch('/auth/passkey/challenge').then(r => r.json());

  // Trigger device authenticator (Touch ID, Face ID, Windows Hello, etc.)
  const assertion = await navigator.credentials.get({
    publicKey: {
      challenge: base64urlDecode(opts.challenge),
      rpId: 'app.example.com',          // must match the registered origin
      allowCredentials: opts.allowCredentials,
      userVerification: 'required',    // require biometric / PIN
    }
  });

  // Send signed assertion to server for verification
  await fetch('/auth/passkey/verify', {
    method: 'POST',
    body: JSON.stringify(serializeAssertion(assertion)),
  });
}

from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError

# OWASP recommended minimum: 46 MB memory, 1 iteration, 1 thread
ph = PasswordHasher(memory_cost=47104, time_cost=1, parallelism=1)

def hash_password(plaintext: str) -> str:
    return ph.hash(plaintext)   # returns '$argon2id$v=19$m=47104,t=1,p=1$...'

def verify_password(stored_hash: str, plaintext: str) -> bool:
    try:
        ph.verify(stored_hash, plaintext)
        if ph.check_needs_rehash(stored_hash):
            # Re-hash with updated parameters transparently
            return True, ph.hash(plaintext)
        return True, None
    except VerifyMismatchError:
        return False, None

import bcrypt

def hash_password(plaintext: str) -> bytes:
    # Encode first; bcrypt operates on bytes
    # Note: bcrypt silently truncates at 72 bytes
    password_bytes = plaintext.encode('utf-8')
    salt = bcrypt.gensalt(rounds=12)  # cost factor 12
    return bcrypt.hashpw(password_bytes, salt)

def verify_password(stored_hash: bytes, plaintext: str) -> bool:
    return bcrypt.checkpw(plaintext.encode('utf-8'), stored_hash)

# To avoid 72-byte truncation for long passphrases:
import hashlib, base64
def prehash(plaintext: str) -> str:
    # SHA-256 produces 44-char base64 output, safely under 72 bytes
    digest = hashlib.sha256(plaintext.encode()).digest()
    return base64.b64encode(digest).decode()

import CryptoKit
import Foundation

func generatePKCE() -> (verifier: String, challenge: String) {
    // RFC 7636: verifier must be 43-128 chars from unreserved URI chars
    let verifierData = (0..<32).map { _ in UInt8.random(in: 0...255) }
    let verifier = Data(verifierData)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")

    // S256 method: SHA256 then base64url
    let hash = SHA256.hash(data: Data(verifier.utf8))
    let challenge = Data(hash)
        .base64EncodedString()
        .replacingOccurrences(of: "+", with: "-")
        .replacingOccurrences(of: "/", with: "_")
        .replacingOccurrences(of: "=", with: "")

    return (verifier, challenge)
}

// Refresh token rotation (server side)
async function rotateRefreshToken(
  presentedToken: string,
  db: TokenStore
): Promise<TokenPair> {
  const record = await db.findRefreshToken(presentedToken);

  if (!record) {
    throw new Error('Unknown refresh token');
  }
  if (record.used) {
    // Reuse detected: revoke entire family — potential token theft
    await db.revokeFamily(record.familyId);
    throw new Error('Refresh token reuse detected — session invalidated');
  }

  // Mark old token as used, issue new pair
  await db.markUsed(record.id);
  const newAccessToken  = issueAccessToken(record.userId);
  const newRefreshToken = await db.issueRefreshToken(record.userId, record.familyId);
  return { accessToken: newAccessToken, refreshToken: newRefreshToken };
}

# Nginx: configure HSTS with includeSubDomains and preload
server {
    listen 443 ssl http2;
    server_name example.com;

    # HSTS: 1 year, apply to all subdomains, eligible for preload list
    add_header Strict-Transport-Security
        "max-age=31536000; includeSubDomains; preload"
        always;

    # Redirect all HTTP traffic to HTTPS
    # (backup for clients that haven't cached the HSTS policy)
}
